import { toPathTemplate } from '@skmtc/lang-typescript'
import type { OasOperation } from '@skmtc/core'

type ClientMethodArgs = {
  operation: OasOperation
  methodName: string
  zodResponseName: string
}

export class ClientMethod {
  methodName: string
  path: string
  method: string
  pathParams: string[]
  hasBody: boolean
  zodResponseName: string

  constructor({ operation, methodName, zodResponseName }: ClientMethodArgs) {
    this.methodName = methodName
    this.path = operation.path
    this.method = operation.method
    this.pathParams = operation.toParams(['path']).map(({ name }) => name)
    this.hasBody = ['post', 'put', 'patch'].includes(operation.method)
    this.zodResponseName = zodResponseName
  }

  toString(): string {
    const params = [
      ...this.pathParams.map(name => `${name}: string`),
      ...(this.hasBody ? ['body: unknown'] : [])
    ].join(', ')

    const init = [
      `method: '${this.method.toUpperCase()}'`,
      ...(this.hasBody
        ? [`headers: { 'Content-Type': 'application/json' }`, `body: JSON.stringify(body)`]
        : [])
    ].join(',\n      ')

    return `async ${this.methodName}(${params}) {
    const res = await fetch(\`${toPathTemplate(this.path)}\`, {
      ${init}
    })

    if (!res.ok) {
      throw new Error(await res.text())
    }

    return ${this.zodResponseName}.parse(await res.json())
  }`
  }
}
===END===

DONE — `@exp/gen-api-client` is an operation-entry generator using the accumulator composition shape: the entry's transform computes the tag-derived identity via statics (`toIdentifierName`/`toExportPath` on `ApiClientBase`, identifier kind `class`, export path `@/client/<Tag>Client.generated.ts`), then does `findDefinition ?? insertOperation(...).definition` so each tag's client class is constructed exactly once and every subsequent operation with that tag is `append`ed as a method. Method names are derived deterministically from method + path (`GET /orders/{id}` → `getOrdersId`), path parameters become typed method parameters templated into the `fetch` URL via `toPathTemplate`, and POST/PUT/PATCH bodies are JSON-stringified. Response validation goes through the engine: `append` calls `this.insertNormalizedModel(ZodProjection, { schema: operation.toSuccessResponse()...  })`, so gen-zod materializes each response model once in its own file (shared `$ref` models like `Order` dedupe through the cache), the import into the client file is auto-stitched by the Driver, and each method returns `<zodName>.parse(await res.json())` using the cached peer name read off the returned definition's `identifier.name`. The package's own `deno.json` deliberately declares no `@skmtc/*` import pins so all resolution flows through the workspace root's wiring, avoiding version skew with the pre-wired `@skmtc/core`, `@skmtc/lang-typescript`, and `@skmtc/gen-zod`.

